-- Only synthetic rollback-only fixtures. Run against the isolated local demo.
\set ON_ERROR_STOP on
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','get_invoice_billing_snapshot',array[]::text[],'billing snapshot RPC exists');
select has_function('public','set_self_billing_consent',array['uuid','boolean','timestamp with time zone','boolean'],'explicit owner consent RPC exists');
select has_function('public','confirm_invoice_billing',array['uuid','uuid','timestamp with time zone','boolean'],'owner confirmation RPC exists');
select has_function('public','get_invoice_billing_quote',array['uuid[]'],'server approval quote exists');
create function pg_temp.bid(n integer) returns uuid language sql immutable as $$select ('96000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.targets(ns integer[]) returns jsonb language sql as $$
 select jsonb_agg(jsonb_build_object('id',t.id,'expected_updated_at',t.updated_at,'approval_id',null,'approval_updated_at',null) order by t.id)
 from public.timelogs t where id in(select pg_temp.bid(n) from unnest(ns)n)
$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.bid(n),'billing-'||n||'@example.invalid',case when n=1 then '{"role":"coo"}'::jsonb else '{}'::jsonb end from generate_series(1,5)n;
delete from public.user_roles where user_id in(select pg_temp.bid(n) from generate_series(1,5)n);
delete from public.profiles where user_id in(select pg_temp.bid(n) from generate_series(1,5)n);
insert into public.profiles(id,user_id,first_name,last_name,ico,bank_account,billing_street,billing_zip,billing_city,billing_country,hourly_rate)
 select pg_temp.bid(n+10),pg_temp.bid(n),'Billing fixture',n::text,'12345678','123/0800','Test street','10000','Praha','CZ',250 from generate_series(1,5)n;
insert into public.user_roles(user_id,role) values(pg_temp.bid(1),'crew'),(pg_temp.bid(2),'crew'),(pg_temp.bid(3),'crewhead'),(pg_temp.bid(4),'coo'),(pg_temp.bid(5),'coo');
insert into public.clients(id,name,ico,street,zip,city,country) values(pg_temp.bid(50),'Billing buyer','87654321','Buyer street','10000','Praha','CZ');
insert into public.projects(id,name,job_number,client_id) values(pg_temp.bid(51),'Billing project','BILL-TEST',pg_temp.bid(50));
insert into public.events(id,name,project_id,job_number,date_from,date_to,meal_allowance_enabled) select pg_temp.bid(n),'Billing fixture '||n,pg_temp.bid(51),'BILL-'||n,'2099-01-01','2099-01-03',true from generate_series(101,120)n;
insert into public.timelogs(id,event_id,contractor_id,status,km) select pg_temp.bid(n+100),pg_temp.bid(n),pg_temp.bid(11),case when n in(109,110) then 'pending_ch'::public.timelog_status else 'pending_coo'::public.timelog_status end,case when n in(101,109) then null when n in(102,103) then 0 else 10 end from generate_series(101,120)n;
insert into public.timelog_days(timelog_id,date,time_from,time_to,day_type,meals)
 select pg_temp.bid(n+100),('2099-01-01'::date+d),'08:00',case when n=103 then '16:20' when n=104 then '20:00' else '18:00' end,'provoz',case when n=104 then array['obed','vecere'] else array['obed'] end from generate_series(101,120)n cross join generate_series(0,2)d where n<>103 or d=0;
update public.events set meal_allowance_enabled=false where id=pg_temp.bid(105);
update public.events set project_id=null where id in(pg_temp.bid(106),pg_temp.bid(118));

update public.events set contact_profile_id=pg_temp.bid(14),contact_approves_hours=true where id in(pg_temp.bid(109),pg_temp.bid(110));
insert into public.shift_workflows(id,created_by) values(pg_temp.bid(79),pg_temp.bid(3));
insert into public.shift_workflow_events(workflow_id,event_id,position) values(pg_temp.bid(79),pg_temp.bid(109),0),(pg_temp.bid(79),pg_temp.bid(110),1);
insert into public.shift_workflow_rounds(id,workflow_id,contractor_id,contractor_user_id,expected_item_count,status,created_by)
 values(pg_temp.bid(80),pg_temp.bid(79),pg_temp.bid(11),pg_temp.bid(1),2,'pending_ch',pg_temp.bid(1));
insert into public.shift_workflow_round_items(round_id,timelog_id,event_id,position) values(pg_temp.bid(80),pg_temp.bid(209),pg_temp.bid(109),0),(pg_temp.bid(80),pg_temp.bid(210),pg_temp.bid(110),1);
create function pg_temp.round_targets() returns jsonb language sql as $$select jsonb_agg(jsonb_build_object('id',t.id,'expected_updated_at',t.updated_at,'expected_status',t.status) order by t.id) from public.timelogs t where id in(pg_temp.bid(209),pg_temp.bid(210))$$;

update private.invoice_billing_jobs set available_at='infinity',locked_until='infinity' where statement_id in(select id from public.invoice_billing_statements where contractor_id<>pg_temp.bid(11));
create temporary table saved(k text primary key,v jsonb);
grant all on saved to authenticated,service_role;
update public.events set project_id=null where id=pg_temp.bid(104);

select has_function('public','repair_invoice_billing_distance',array['uuid','uuid','uuid','timestamp with time zone','jsonb'],'narrow authenticated distance repair exists');
select has_function('public','retry_invoice_billing_job',array['uuid','uuid','uuid','timestamp with time zone','timestamp with time zone'],'narrow failed job recovery exists');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
insert into saved values('grant',public.set_self_billing_consent(pg_temp.bid(700),true,null,true));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(4),'role','authenticated')::text,true);
insert into saved values('null_quote',public.get_invoice_billing_quote(array[pg_temp.bid(201)]));
select public.resolve_timelog_approvals_atomic(pg_temp.targets(array[201]),'approved','',((select v from saved where k='null_quote')->>'id')::uuid);
select ok((select financial_snapshot->'reports'->0->'km'='null'::jsonb and not financial_verified and status='blocked' from public.invoice_billing_statements where id=(select statement_id from public.invoice_billing_sources where timelog_id=pg_temp.bid(201))),'quoted NULL distance stays invalid and unverified');
update public.profiles set bank_account='' where id=pg_temp.bid(11);
insert into saved values('supplier_quote',public.get_invoice_billing_quote(array[pg_temp.bid(202)]));
select public.resolve_timelog_approvals_atomic(pg_temp.targets(array[202]),'approved','',((select v from saved where k='supplier_quote')->>'id')::uuid);
insert into saved values('supplier',(select to_jsonb(s) from public.invoice_billing_statements s where id=(select statement_id from public.invoice_billing_sources where timelog_id=pg_temp.bid(202))));
select is((select v->>'consent_grant_id' from saved where k='supplier'),(select v->>'active_grant_id' from saved where k='grant'),'initial supplier blocker preserves eligible standing grant');
reset role;
select is((select count(*) from private.invoice_billing_jobs where statement_id=((select v from saved where k='supplier')->>'id')::uuid and kind='issue'),1::bigint,'initial legal blocker has durable waiting job');
update private.invoice_billing_jobs set available_at='infinity',locked_until='infinity' where statement_id<>((select v from saved where k='supplier')->>'id')::uuid;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into saved values('supplier_jobs',public.claim_invoice_billing_jobs(100));
insert into saved select 'supplier_wait',public.process_invoice_billing_job((j->>'id')::uuid,(j->>'lease_token')::uuid) from saved,jsonb_array_elements(v->'jobs')j where k='supplier_jobs';
select is((select v->>'status' from saved where k='supplier_wait'),'blocked','legal blocker waits rather than cancels');
reset role;
select is((select attempts from private.invoice_billing_jobs where statement_id=((select v from saved where k='supplier')->>'id')::uuid and kind='issue'),0,'legal waiting does not consume attempts');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(4),'role','authenticated')::text,true);
update public.profiles set hourly_rate=999 where id=pg_temp.bid(11);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
update public.profiles set bank_account='456/0800' where id=pg_temp.bid(11);
select public.refresh_invoice_billing_preview(pg_temp.bid(701),((select v from saved where k='supplier')->>'id')::uuid,(select updated_at from public.invoice_billing_statements where id=((select v from saved where k='supplier')->>'id')::uuid));
reset role;
update private.invoice_billing_jobs set available_at=clock_timestamp()-interval '1 second' where statement_id=((select v from saved where k='supplier')->>'id')::uuid and kind='issue';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into saved values('supplier_repaired_jobs',public.claim_invoice_billing_jobs(100));
select public.process_invoice_billing_job((j->>'id')::uuid,(j->>'lease_token')::uuid) from saved,jsonb_array_elements(v->'jobs')j where k='supplier_repaired_jobs';
reset role;
select is((select total_amount from public.invoices where billing_statement_id=((select v from saved where k='supplier')->>'id')::uuid),8550::numeric,'owner supplier repair automatically resumes original grant with frozen rate');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(4),'role','authenticated')::text,true);
update public.profiles set hourly_rate=250 where id=pg_temp.bid(11);
insert into saved values('buyer_quote',public.get_invoice_billing_quote(array[pg_temp.bid(204)]));
select public.resolve_timelog_approvals_atomic(pg_temp.targets(array[204]),'approved','',((select v from saved where k='buyer_quote')->>'id')::uuid);
insert into saved values('buyer',(select to_jsonb(s) from public.invoice_billing_statements s where id=(select statement_id from public.invoice_billing_sources where timelog_id=pg_temp.bid(204))));
select is((select v->>'consent_grant_id' from saved where k='buyer'),(select v->>'active_grant_id' from saved where k='grant'),'initial buyer blocker preserves original grant');
update public.events set project_id=pg_temp.bid(51) where id=pg_temp.bid(104);
update public.profiles set hourly_rate=999 where id=pg_temp.bid(11);
select public.prepare_invoice_billing_selection(pg_temp.bid(702),array[pg_temp.bid(204)]);
select is((select consent_grant_id::text from public.invoice_billing_statements where id=((select v from saved where k='buyer')->>'id')::uuid),(select v->>'active_grant_id' from saved where k='grant'),'exact COO buyer repair retains eligible grant');
reset role;
update private.invoice_billing_jobs set available_at='infinity',locked_until='infinity' where statement_id<>((select v from saved where k='buyer')->>'id')::uuid;
update private.invoice_billing_jobs set available_at=clock_timestamp()-interval '1 second' where statement_id=((select v from saved where k='buyer')->>'id')::uuid and kind='issue';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into saved values('buyer_jobs',public.claim_invoice_billing_jobs(100));
select public.process_invoice_billing_job((j->>'id')::uuid,(j->>'lease_token')::uuid) from saved,jsonb_array_elements(v->'jobs')j where k='buyer_jobs';
reset role;
select is((select total_amount from public.invoices where billing_statement_id=((select v from saved where k='buyer')->>'id')::uuid),10556::numeric,'COO buyer repair resumes automatic issuance without repricing');

-- A user can wake a queued transient failure without resetting its budget.
reset role;
update private.invoice_billing_jobs set available_at='infinity',locked_until='infinity';
update private.invoice_billing_jobs set available_at='1900-01-01' where statement_id=((select v from saved where k='buyer')->>'id')::uuid and kind='pdf';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into saved values('wake_claim',public.claim_invoice_billing_jobs(1));
select public.complete_invoice_billing_job((j->>'id')::uuid,(j->>'lease_token')::uuid,null,'DISPOSABLE transient PDF failure') from saved,jsonb_array_elements(v->'jobs')j where k='wake_claim';
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
insert into saved select 'wake_job',j from jsonb_array_elements(public.get_invoice_billing_snapshot()->'jobs')j where j->>'statement_id'=(select v->>'id' from saved where k='buyer') and j->>'kind'='pdf';
insert into saved values('wake_statement',(select to_jsonb(s) from public.invoice_billing_statements s where id=((select v from saved where k='buyer')->>'id')::uuid));
select ok((select (v->>'can_retry')::boolean and v->>'attempts'='1' from saved where k='wake_job'),'queued transient failure exposes immediate wake capability');
select lives_ok($$insert into saved values('woken',public.retry_invoice_billing_job(pg_temp.bid(725),((select v from saved where k='wake_statement')->>'id')::uuid,((select v from saved where k='wake_job')->>'id')::uuid,((select v from saved where k='wake_statement')->>'updated_at')::timestamptz,((select v from saved where k='wake_job')->>'updated_at')::timestamptz))$$,'owner wakes queued failure immediately');
select ok((select v->'job'->>'attempts'='1' and v->'job'->>'retry_generation'='0' and v->'job'->'failure_code'='null'::jsonb and not (v->'job'->>'can_retry')::boolean from saved where k='woken'),'wake preserves budget/generation and clears transient presentation');
select lives_ok($$select public.retry_invoice_billing_job(pg_temp.bid(725),((select v from saved where k='wake_statement')->>'id')::uuid,((select v from saved where k='wake_job')->>'id')::uuid,((select v from saved where k='wake_statement')->>'updated_at')::timestamptz,((select v from saved where k='wake_job')->>'updated_at')::timestamptz)$$,'queued wake request replays after presentation clears');
reset role;

-- PDF retry budget and abandoned leases terminate at eight attempts.
update private.invoice_billing_jobs set available_at='infinity',locked_until='infinity';
update private.invoice_billing_jobs set attempts=7,available_at=clock_timestamp()-interval '1 second' where statement_id=((select v from saved where k='buyer')->>'id')::uuid and kind='pdf';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into saved values('pdf_jobs',public.claim_invoice_billing_jobs(1));
insert into saved select 'pdf_failed',public.complete_invoice_billing_job((j->>'id')::uuid,(j->>'lease_token')::uuid,null,'SECRET SERVICE FAILURE fixture') from saved,jsonb_array_elements(v->'jobs')j where k='pdf_jobs';
select is((select v->>'status' from saved where k='pdf_failed'),'failed','eighth transient failure is terminal');
reset role;
update private.invoice_billing_jobs set status='running',attempts=8,locked_until=clock_timestamp()-interval '1 second',lease_token=gen_random_uuid() where statement_id=((select v from saved where k='buyer')->>'id')::uuid and kind='pdf';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(jsonb_array_length(public.claim_invoice_billing_jobs(1)->'jobs'),0,'expired eighth lease is not claimed for a ninth attempt');
reset role;
select is((select status from private.invoice_billing_jobs where statement_id=((select v from saved where k='buyer')->>'id')::uuid and kind='pdf'),'failed','expired budget lease becomes terminal');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
select ok(public.get_invoice_billing_snapshot() ? 'jobs','owner snapshot exposes sanitized durable job state');
select ok(public.get_invoice_billing_snapshot()::text not like '%SECRET SERVICE FAILURE%' and public.get_invoice_billing_snapshot()::text not like '%lease_token%','job snapshot excludes raw errors and lease secrets');
reset role;

set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(4),'role','authenticated')::text,true);
insert into saved values('repair_before',(select to_jsonb(t) from public.timelogs t where id=pg_temp.bid(201)));
insert into saved values('repair_statement',(select to_jsonb(s) from public.invoice_billing_statements s where id=(select statement_id from public.invoice_billing_sources where timelog_id=pg_temp.bid(201))));
insert into saved values('repair_sources',jsonb_build_array(jsonb_build_object('timelog_id',pg_temp.bid(201),'expected_updated_at',(select updated_at from public.timelogs where id=pg_temp.bid(201)),'km',5)));
insert into saved values('repaired',public.repair_invoice_billing_distance(pg_temp.bid(703),((select v from saved where k='repair_statement')->>'id')::uuid,pg_temp.bid(11),((select v from saved where k='repair_statement')->>'updated_at')::timestamptz,(select v from saved where k='repair_sources')));
select is((select v->'statement'->>'total_amount' from saved where k='repaired'),'8578.00','distance-only repair preserves original 7500 hours +1050 meals and adds28 travel despite rate999');
select is((select to_jsonb(t)-array['km','updated_at'] from public.timelogs t where id=pg_temp.bid(201)),(select v-array['km','updated_at'] from saved where k='repair_before'),'distance repair preserves all source fields except km/version');
select ok((select t.updated_at>((select v from saved where k='repair_before')->>'updated_at')::timestamptz from public.timelogs t where id=pg_temp.bid(201)),'repair advances exact source version even inside one transaction');
select is(public.repair_invoice_billing_distance(pg_temp.bid(703),((select v from saved where k='repair_statement')->>'id')::uuid,pg_temp.bid(11),((select v from saved where k='repair_statement')->>'updated_at')::timestamptz,(select v from saved where k='repair_sources')),(select v from saved where k='repaired'),'distance repair replays same result');
select throws_ok($$select public.repair_invoice_billing_distance(pg_temp.bid(704),((select v from saved where k='repaired')->'statement'->>'id')::uuid,pg_temp.bid(11),((select v from saved where k='repaired')->'statement'->>'updated_at')::timestamptz,jsonb_build_array(jsonb_build_object('timelog_id',pg_temp.bid(201),'expected_updated_at',(select updated_at from public.timelogs where id=pg_temp.bid(201)),'km',10)))$$,'22023',null::text,'verified frozen distance cannot be edited by repair');
reset role;
select is((select count(*) from private.invoice_billing_repair_permits),0::bigint,'distance repair clears exact transaction permits');

-- Only owner Crew/COO can recover failed PDF delivery, against its original ID.
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
insert into saved values('retry_statement',(select to_jsonb(s) from public.invoice_billing_statements s where id=((select v from saved where k='buyer')->>'id')::uuid));
insert into saved select 'retry_job',j from jsonb_array_elements(public.get_invoice_billing_snapshot()->'jobs')j where j->>'statement_id'=(select v->>'id' from saved where k='buyer') and j->>'kind'='pdf';
select is((select (v->>'can_retry')::boolean from saved where k='retry_job'),true,'owner sees failed PDF recovery capability');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(3),'role','authenticated')::text,true);
select ok((select not (j->>'can_retry')::boolean from jsonb_array_elements(public.get_invoice_billing_snapshot()->'jobs')j where j->>'id'=(select v->>'id' from saved where k='retry_job')),'CH management snapshot cannot retry');
select throws_ok($$select public.retry_invoice_billing_job(pg_temp.bid(707),((select v from saved where k='retry_statement')->>'id')::uuid,((select v from saved where k='retry_job')->>'id')::uuid,((select v from saved where k='retry_statement')->>'updated_at')::timestamptz,((select v from saved where k='retry_job')->>'updated_at')::timestamptz)$$,'42501',null::text,'CH cannot recover PDF job');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(2),'role','authenticated')::text,true);
select ok(not exists(select 1 from jsonb_array_elements(public.get_invoice_billing_snapshot()->'jobs')j where j->>'id'=(select v->>'id' from saved where k='retry_job')),'foreign owner cannot read job');
select throws_ok($$select public.retry_invoice_billing_job(pg_temp.bid(707),((select v from saved where k='retry_statement')->>'id')::uuid,((select v from saved where k='retry_job')->>'id')::uuid,((select v from saved where k='retry_statement')->>'updated_at')::timestamptz,((select v from saved where k='retry_job')->>'updated_at')::timestamptz)$$,'42501',null::text,'foreign owner cannot recover PDF job');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
select throws_ok($$select public.retry_invoice_billing_job(pg_temp.bid(708),((select v from saved where k='retry_statement')->>'id')::uuid,((select v from saved where k='retry_job')->>'id')::uuid,((select v from saved where k='retry_statement')->>'updated_at')::timestamptz,'2000-01-01')$$,'PT409',null::text,'stale failed job version rejects recovery');
insert into saved values('retry',public.retry_invoice_billing_job(pg_temp.bid(707),((select v from saved where k='retry_statement')->>'id')::uuid,((select v from saved where k='retry_job')->>'id')::uuid,((select v from saved where k='retry_statement')->>'updated_at')::timestamptz,((select v from saved where k='retry_job')->>'updated_at')::timestamptz));
select ok((select v->'job'->>'status'='queued' and v->'job'->>'attempts'='0' and v->'job'->>'retry_generation'='1' and v->'job'->>'invoice_id'=(select v->>'invoice_id' from saved where k='retry_job') from saved where k='retry'),'recovery resets finite generation against original invoice');
select is(public.retry_invoice_billing_job(pg_temp.bid(707),((select v from saved where k='retry_statement')->>'id')::uuid,((select v from saved where k='retry_job')->>'id')::uuid,((select v from saved where k='retry_statement')->>'updated_at')::timestamptz,((select v from saved where k='retry_job')->>'updated_at')::timestamptz),(select v from saved where k='retry'),'recovery request replays same result');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into saved values('retry_claim',public.claim_invoice_billing_jobs(1));
insert into saved select 'retry_render',public.process_invoice_billing_job((j->>'id')::uuid,(j->>'lease_token')::uuid) from saved,jsonb_array_elements(v->'jobs')j where k='retry_claim';
select is((select v->'invoice'->>'id' from saved where k='retry_render'),(select v->>'invoice_id' from saved where k='retry_job'),'retry renderer receives exactly the original invoice');
reset role;
select is((select count(*) from public.invoices where billing_statement_id=((select v from saved where k='buyer')->>'id')::uuid),1::bigint,'PDF failure/recovery allocates no second invoice or number');
-- Ready source→changed buyer→exact repair keeps original standing eligibility.
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(4),'role','authenticated')::text,true);
update public.profiles set hourly_rate=250 where id=pg_temp.bid(11);
insert into saved values('ready_quote',public.get_invoice_billing_quote(array[pg_temp.bid(203)]));
select public.resolve_timelog_approvals_atomic(pg_temp.targets(array[203]),'approved','',((select v from saved where k='ready_quote')->>'id')::uuid);
insert into saved values('ready',(select to_jsonb(s) from public.invoice_billing_statements s where id=(select statement_id from public.invoice_billing_sources where timelog_id=pg_temp.bid(203))));
update public.clients set street='Buyer changed after ready' where id=pg_temp.bid(50);
update public.profiles set hourly_rate=999 where id=pg_temp.bid(11);
select public.prepare_invoice_billing_selection(pg_temp.bid(710),array[pg_temp.bid(203)]);
select is((select consent_grant_id::text from public.invoice_billing_statements where id=((select v from saved where k='ready')->>'id')::uuid),(select v->>'active_grant_id' from saved where k='grant'),'ready buyer repair keeps original grant');
reset role;
update private.invoice_billing_jobs set available_at='infinity',locked_until='infinity';
update private.invoice_billing_jobs set available_at=clock_timestamp()-interval '1 second' where statement_id=((select v from saved where k='ready')->>'id')::uuid and kind='issue';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into saved values('ready_jobs',public.claim_invoice_billing_jobs(1));
select public.process_invoice_billing_job((j->>'id')::uuid,(j->>'lease_token')::uuid) from saved,jsonb_array_elements(v->'jobs')j where k='ready_jobs';
reset role;
select is((select total_amount from public.invoices where billing_statement_id=((select v from saved where k='ready')->>'id')::uuid),2333.33::numeric,'ready buyer repair automatically issues frozen fractional amount');
-- Late opt-in never creates a job; revoked/regranted eligibility never revives.
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
select public.set_self_billing_consent(pg_temp.bid(711),false,(select updated_at from public.invoice_billing_consents where contractor_id=pg_temp.bid(11)),false);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(4),'role','authenticated')::text,true);
insert into saved values('late_quote',public.get_invoice_billing_quote(array[pg_temp.bid(205)]));
select public.resolve_timelog_approvals_atomic(pg_temp.targets(array[205]),'approved','',((select v from saved where k='late_quote')->>'id')::uuid);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
select public.set_self_billing_consent(pg_temp.bid(712),true,(select updated_at from public.invoice_billing_consents where contractor_id=pg_temp.bid(11)),true);
reset role;
select is((select count(*) from private.invoice_billing_jobs where statement_id=(select statement_id from public.invoice_billing_sources where timelog_id=pg_temp.bid(205)) and kind='issue'),0::bigint,'late opt-in does not schedule historical quoted approval');
update private.invoice_billing_jobs set available_at=clock_timestamp()-interval '1 second' where statement_id=((select v from saved where k='repair_statement')->>'id')::uuid and kind='issue';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into saved values('regrant_jobs',public.claim_invoice_billing_jobs(1));
insert into saved select 'regrant_cancelled',public.process_invoice_billing_job((j->>'id')::uuid,(j->>'lease_token')::uuid) from saved,jsonb_array_elements(v->'jobs')j where k='regrant_jobs';
select is((select v->>'status' from saved where k='regrant_cancelled'),'cancelled','regrant does not revive old repaired-source eligibility');
reset role;
select is((select attempts from private.invoice_billing_jobs where statement_id=((select v from saved where k='repair_statement')->>'id')::uuid and kind='issue'),0,'consent cancellation consumes no retry budget');
-- A full shared round admits only invalid km repairs through exact permits.
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(3),'role','authenticated')::text,true);
select public.transition_shift_workflow_round_atomic(pg_temp.bid(713),pg_temp.bid(80),(select updated_at from public.shift_workflow_rounds where id=pg_temp.bid(80)),pg_temp.round_targets(),'handoff','',null,null);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(4),'role','authenticated')::text,true);
update public.profiles set hourly_rate=250 where id=pg_temp.bid(11);
insert into saved values('shared_quote',public.get_invoice_billing_quote(array[pg_temp.bid(209),pg_temp.bid(210)]));
select public.transition_shift_workflow_round_atomic(pg_temp.bid(714),pg_temp.bid(80),(select updated_at from public.shift_workflow_rounds where id=pg_temp.bid(80)),pg_temp.round_targets(),'approve','',null,null,((select v from saved where k='shared_quote')->>'id')::uuid);
insert into saved values('shared_statement',(select to_jsonb(s) from public.invoice_billing_statements s where id=(select statement_id from public.invoice_billing_sources where timelog_id=pg_temp.bid(209))));
insert into saved values('shared_sources',(select jsonb_agg(jsonb_build_object('timelog_id',t.id,'expected_updated_at',t.updated_at,'km',case when t.id=pg_temp.bid(209) then 20 else 10 end) order by t.id) from public.timelogs t where id in(pg_temp.bid(209),pg_temp.bid(210))));
select throws_ok($$update public.timelogs set km=20 where id=pg_temp.bid(209)$$,'42501',null::text,'direct COO km edit still denied without exact permit');
select throws_ok($$select public.repair_invoice_billing_distance(pg_temp.bid(715),((select v from saved where k='shared_statement')->>'id')::uuid,pg_temp.bid(11),((select v from saved where k='shared_statement')->>'updated_at')::timestamptz,jsonb_build_array((select v->0 from saved where k='shared_sources')))$$,'22023',null::text,'repair cannot select partial shared source set');
select throws_ok($$select public.repair_invoice_billing_distance(pg_temp.bid(716),((select v from saved where k='shared_statement')->>'id')::uuid,pg_temp.bid(11),((select v from saved where k='shared_statement')->>'updated_at')::timestamptz,jsonb_set((select v from saved where k='shared_sources'),'{1,km}','11'))$$,'22023',null::text,'repair cannot edit another valid shared km');
select ok((select km is null from public.timelogs where id=pg_temp.bid(209)),'failed multi-source repair rolls back all earlier row mutations');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
select throws_ok($$select public.repair_invoice_billing_distance(pg_temp.bid(717),((select v from saved where k='shared_statement')->>'id')::uuid,pg_temp.bid(11),((select v from saved where k='shared_statement')->>'updated_at')::timestamptz,(select v from saved where k='shared_sources'))$$,'42501',null::text,'owner Crew cannot repair approved km');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(3),'role','authenticated')::text,true);
select throws_ok($$select public.repair_invoice_billing_distance(pg_temp.bid(717),((select v from saved where k='shared_statement')->>'id')::uuid,pg_temp.bid(11),((select v from saved where k='shared_statement')->>'updated_at')::timestamptz,(select v from saved where k='shared_sources'))$$,'42501',null::text,'CH cannot repair approved km');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(4),'role','authenticated')::text,true);
select throws_ok($$select public.repair_invoice_billing_distance(pg_temp.bid(717),((select v from saved where k='shared_statement')->>'id')::uuid,pg_temp.bid(12),((select v from saved where k='shared_statement')->>'updated_at')::timestamptz,(select v from saved where k='shared_sources'))$$,'42501',null::text,'repair binds contractor identity');
update public.profiles set hourly_rate=999 where id=pg_temp.bid(11);
insert into saved values('shared_repaired',public.repair_invoice_billing_distance(pg_temp.bid(717),((select v from saved where k='shared_statement')->>'id')::uuid,pg_temp.bid(11),((select v from saved where k='shared_statement')->>'updated_at')::timestamptz,(select v from saved where k='shared_sources')));
select is((select v->'statement'->>'total_amount' from saved where k='shared_repaired'),'17268.00','shared repair retains both original hourly rates and valid km');
select is((select status::text from public.shift_workflow_rounds where id=pg_temp.bid(80)),'approved','km repair preserves frozen round approval');
reset role;
select is((select count(*) from private.invoice_billing_repair_permits),0::bigint,'all successful/failed shared repairs leave no permits');
select is((select count(*) from public.invoice_billing_source_history where statement_id=((select v from saved where k='shared_statement')->>'id')::uuid),4::bigint,'shared invalid/corrected source versions retain immutable history');


-- Failed automatic issuance cannot be revived by revoked or newly granted consent.
update private.invoice_billing_jobs set available_at='infinity',locked_until='infinity';
update private.invoice_billing_jobs set attempts=7,available_at='1900-01-01' where statement_id=((select v from saved where k='shared_statement')->>'id')::uuid and kind='issue';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into saved values('issue_fail_claim',public.claim_invoice_billing_jobs(1));
select public.complete_invoice_billing_job((j->>'id')::uuid,(j->>'lease_token')::uuid,null,'DISPOSABLE issue failure') from saved,jsonb_array_elements(v->'jobs')j where k='issue_fail_claim';
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(1),'role','authenticated')::text,true);
insert into saved select 'failed_issue',j from jsonb_array_elements(public.get_invoice_billing_snapshot()->'jobs')j where j->>'statement_id'=(select v->>'id' from saved where k='shared_statement') and j->>'kind'='issue';
select ok((select (v->>'can_retry')::boolean from saved where k='failed_issue'),'failed issue recovery allowed under original still-active grant');
select public.set_self_billing_consent(pg_temp.bid(718),false,(select updated_at from public.invoice_billing_consents where contractor_id=pg_temp.bid(11)),false);
select ok((select not (j->>'can_retry')::boolean from jsonb_array_elements(public.get_invoice_billing_snapshot()->'jobs')j where j->>'id'=(select v->>'id' from saved where k='failed_issue')),'revocation immediately disables failed issue recovery capability');
select public.set_self_billing_consent(pg_temp.bid(719),true,(select updated_at from public.invoice_billing_consents where contractor_id=pg_temp.bid(11)),true);
select ok((select not (j->>'can_retry')::boolean from jsonb_array_elements(public.get_invoice_billing_snapshot()->'jobs')j where j->>'id'=(select v->>'id' from saved where k='failed_issue')),'new grant never restores old failed issue eligibility');
select throws_ok($$select public.retry_invoice_billing_job(pg_temp.bid(720),((select v from saved where k='shared_statement')->>'id')::uuid,((select v from saved where k='failed_issue')->>'id')::uuid,((select v from saved where k='shared_repaired')->'statement'->>'updated_at')::timestamptz,((select v from saved where k='failed_issue')->>'updated_at')::timestamptz)$$,'22023','invoice_billing_job_recovery_inactive','RPC rejects recovery under a replacement grant');
select public.confirm_invoice_billing(pg_temp.bid(721),((select v from saved where k='shared_statement')->>'id')::uuid,((select v from saved where k='shared_repaired')->'statement'->>'updated_at')::timestamptz,true);
select ok((select not (j->>'can_retry')::boolean from jsonb_array_elements(public.get_invoice_billing_snapshot()->'jobs')j where j->>'id'=(select v->>'id' from saved where k='failed_issue')),'issued statement has no remaining issue retry capability');
reset role;
select is((select count(*) from public.invoices where billing_statement_id=((select v from saved where k='shared_statement')->>'id')::uuid),1::bigint,'fresh individual consent safely recovers failed issuance exactly once');

select * from finish();
rollback;
